create or replace function public.post_author(pid uuid) returns table(display_name text,badge text) language sql stable security definer set search_path='' as $$select case when p.anonymous then 'Anonymous' else pr.display_name end,case when p.anonymous then 'Verified Student' else 'Verified Student' || case when pr.role='student' and pr.graduation_year<=extract(year from now())+1 then ' · Senior' when pr.role='moderator' or pr.role='admin' then ' · Moderator' when pr.role='club_head' then ' · Club Head' when pr.role='alumni' then ' · Alumni' else '' end end from public.posts p join private.post_authors pa on pa.post_id=p.id join public.profiles pr on pr.id=pa.user_id where p.id=pid and p.college_id=private.college() and private.not_banned()$$;
